// Replaced at build time by `define` in vite.config.ts.
declare const __APP_VERSION__: string;
/** Build time plus short commit; changes on every deploy (used to detect updates). */
declare const __BUILD_ID__: string;
declare const __BUILD_TIME__: string;
/** Full commit hash the build was made from, or '' when unknown. */
declare const __COMMIT_SHA__: string;
/** GitHub URL of that commit (CI builds only), or ''. */
declare const __COMMIT_URL__: string;
